def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def stock(s):
 c=collections.Counter()
 for x in (s.get('raid') or {}).get('inventory',{}).get('slots',[]):
  if x:c['food' if x['item']['kind']=='provision' else (x['item']['id'] or x['item']['kind'])]+=x['amount']
 return dict(c)
def heroes(s,frame):
 raid=s.get('raid') or {};out={h['guid']:dict(h) for h in raid.get('heroes',[]) if h['guid'] in raid.get('party',[])}
 b=raid.get('battle')
 if b:
  bridge={h['unit_id']:h['guid'] for h in frame.get('battle_heroes') or []}
  units={u['id']:u for u in b['units'] if u['id'] in bridge and not u['corpse']}
  for uid,guid in bridge.items():
   if guid in out:
    if uid in units:
     u=units[uid];out[guid].update(hp=u['hp'],maximum_hp=u['max_hp'],stress=u['stress'],alive=True,resolve=u['resolve'])
    else:out[guid].update(hp=0,alive=False)
 return out

def capability(s):
 rows=list(s['training'].values());return {k:any(h[k] for h in rows) for k in ['heal','relief','control']}
def usable(s):
 r=s.get('raid') or {};ans=[];bag=r.get('inventory',{}).get('slots',[])
 for a in r.get('actions',[]):
  if isinstance(a,dict) and a.get('Camp')=='Start':ans.append('camp')
  if isinstance(a,dict) and 'Use' in a:
   x=bag[a['Use']['slot']]
   if x:
    item=x['item'];name='food' if item['kind']=='provision' else item['id']
    if name in ['food','bandage','antivenom','laudanum']:ans.append(name)
 return sorted(set(ans))

